    "body": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Forms · MCQ Form Builder</title>\n<link rel=\"icon\" href=\"/assets/favicon.svg\" type=\"image/svg+xml\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=EB+Garamond:wght@500&family=Inter:wght@400;500;600&family=Noto+Sans+Devanagari:wght@400;500;600&display=swap\">\n<link rel=\"stylesheet\" href=\"/assets/styles.css\">\n</head>\n<body>\n\n<header class=\"top\">\n  <div class=\"top-inner\">\n    <a class=\"brand\" href=\"/\"><img src=\"/assets/favicon.svg\" width=\"22\" height=\"22\" alt=\"\">MCQ Form Builder</a>\n    <nav class=\"nav\" aria-label=\"Main\">\n      <a href=\"/\">New quiz</a>\n      <a href=\"/forms\" aria-current=\"page\">Forms</a>\n      <a href=\"/connectors\">Connectors</a>\n    </nav>\n    <div class=\"account\">\n      <img id=\"avatar\" alt=\"\" hidden referrerpolicy=\"no-referrer\">\n      <span id=\"account\"></span>\n      <button class=\"text-btn\" id=\"signout\" type=\"button\">Sign out</button>\n    </div>\n  </div>\n</header>\n\n<main class=\"page\">\n  <div class=\"page-head\">\n    <h1 class=\"page-title\">Forms</h1>\n    <button class=\"btn btn-secondary\" id=\"refresh\" type=\"button\">Refresh responses</button>\n  </div>\n  <div class=\"stats\" id=\"stats\">\n    <div class=\"stat\"><span class=\"stat-label\">Forms</span><b class=\"num\" id=\"st-forms\">–</b></div>\n    <div class=\"stat\"><span class=\"stat-label\">Questions</span><b class=\"num\" id=\"st-questions\">–</b></div>\n    <div class=\"stat\"><span class=\"stat-label\">Responses</span><b class=\"num\" id=\"st-responses\">–</b></div>\n  </div>\n  <div class=\"tabs\" role=\"tablist\" aria-label=\"Show\">\n    <button class=\"tab\" role=\"tab\" id=\"tab-all\" aria-selected=\"true\" type=\"button\">All</button>\n    <button class=\"tab\" role=\"tab\" id=\"tab-created\" aria-selected=\"false\" type=\"button\">Made</button>\n    <button class=\"tab\" role=\"tab\" id=\"tab-failed\" aria-selected=\"false\" type=\"button\">Failed</button>\n  </div>\n  <div class=\"form-list\" id=\"list\" aria-live=\"polite\"></div>\n</main>\n<div class=\"toast\" id=\"toast\" role=\"status\" hidden></div>\n<script type=\"module\" src=\"/assets/forms.js\"></script>\n</body>\n</html>\n",
