export const MIGRATIONS: { name: string; sql: string }[] = [
  {
    "name": "001_init.sql",
    "sql": "-- MCQ Form Builder schema. Safe to run more than once.\n-- Row level security is switched on with no policies: Supabase's anon/authenticated\n-- roles (PostgREST) see nothing; the app connects as the database owner and bypasses RLS.\n\nCREATE TABLE IF NOT EXISTS users (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  google_sub text NOT NULL UNIQUE,\n  email text NOT NULL,\n  name text NOT NULL DEFAULT '',\n  picture text NOT NULL DEFAULT '',\n  refresh_token_enc text,\n  access_token_enc text,\n  access_token_expires_at timestamptz NOT NULL DEFAULT 'epoch',\n  scopes text NOT NULL DEFAULT '',\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS sessions (\n  id_hash text PRIMARY KEY,\n  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  expires_at timestamptz NOT NULL\n);\nCREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions(user_id);\n\nCREATE TABLE IF NOT EXISTS oauth_states (\n  state text PRIMARY KEY,\n  verifier text NOT NULL,\n  return_to text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS api_tokens (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  name text NOT NULL,\n  token_hash text NOT NULL UNIQUE,\n  prefix text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  last_used_at timestamptz\n);\n\n-- One row per Apps Script run: the script that was executed and the form it made.\nCREATE TABLE IF NOT EXISTS forms (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  title text NOT NULL,\n  description text NOT NULL DEFAULT '',\n  question_count integer NOT NULL,\n  unanswered_count integer NOT NULL DEFAULT 0,\n  payload jsonb NOT NULL,\n  script_source text NOT NULL,\n  status text NOT NULL CHECK (status IN ('pending', 'created', 'failed')),\n  error text,\n  form_id text,\n  edit_url text,\n  published_url text,\n  script_project_id text,\n  response_count integer,\n  accepting_responses boolean,\n  stats_updated_at timestamptz,\n  source text NOT NULL DEFAULT 'api',\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS forms_user_created_idx ON forms(user_id, created_at DESC);\n\nALTER TABLE users ENABLE ROW LEVEL SECURITY;\nALTER TABLE sessions ENABLE ROW LEVEL SECURITY;\nALTER TABLE oauth_states ENABLE ROW LEVEL SECURITY;\nALTER TABLE api_tokens ENABLE ROW LEVEL SECURITY;\nALTER TABLE forms ENABLE ROW LEVEL SECURITY;\n"
  },
  {
    "name": "002_short_url.sql",
    "sql": "-- forms.gle short link for the student URL (Form.shortenFormUrl), when Google provides one.\nALTER TABLE forms ADD COLUMN IF NOT EXISTS short_url text;\n"
  },
  {
    "name": "003_oauth.sql",
    "sql": "-- OAuth 2.1 authorization server for MCP clients (claude.ai custom connectors).\n-- Clients register themselves (RFC 7591), users approve on a consent page, and each approval is a\n-- grant holding a rotating refresh token and short-lived access tokens.\n\nCREATE TABLE IF NOT EXISTS oauth_clients (\n  client_id text PRIMARY KEY,\n  secret_hash text,\n  name text NOT NULL DEFAULT '',\n  redirect_uris jsonb NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS oauth_codes (\n  code_hash text PRIMARY KEY,\n  client_id text NOT NULL REFERENCES oauth_clients(client_id) ON DELETE CASCADE,\n  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  redirect_uri text NOT NULL,\n  code_challenge text NOT NULL,\n  scope text NOT NULL DEFAULT '',\n  expires_at timestamptz NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS oauth_grants (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  client_id text NOT NULL REFERENCES oauth_clients(client_id) ON DELETE CASCADE,\n  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  refresh_hash text NOT NULL UNIQUE,\n  scope text NOT NULL DEFAULT '',\n  created_at timestamptz NOT NULL DEFAULT now(),\n  last_used_at timestamptz,\n  expires_at timestamptz NOT NULL\n);\nCREATE INDEX IF NOT EXISTS oauth_grants_user_idx ON oauth_grants(user_id);\n\nCREATE TABLE IF NOT EXISTS oauth_access_tokens (\n  token_hash text PRIMARY KEY,\n  grant_id uuid NOT NULL REFERENCES oauth_grants(id) ON DELETE CASCADE,\n  expires_at timestamptz NOT NULL\n);\nCREATE INDEX IF NOT EXISTS oauth_access_tokens_grant_idx ON oauth_access_tokens(grant_id);\n\nALTER TABLE oauth_clients ENABLE ROW LEVEL SECURITY;\nALTER TABLE oauth_codes ENABLE ROW LEVEL SECURITY;\nALTER TABLE oauth_grants ENABLE ROW LEVEL SECURITY;\nALTER TABLE oauth_access_tokens ENABLE ROW LEVEL SECURITY;\n"
  }
];
